export const SUBS: { from: number; to: number; text: string }[] = [{"from": 36, "to": 87, "text": "अगर आप एक YouTube Creator हो,"}, {"from": 88, "to": 203, "text": "तो आप जानते हो कि एक अच्छी वीडियो बनाने में कितनी मेहनत लगती है।"}, {"from": 216, "to": 348, "text": "सबसे पहले एक अच्छा topic ढूँढना पड़ता है। फिर research करनी होती है,"}, {"from": 349, "to": 464, "text": "script लिखनी होती है, title और thumbnail तैयार करना होता है,"}, {"from": 465, "to": 604, "text": "और वीडियो publish करने के बाद उसकी performance भी analyze करनी पड़ती है।"}, {"from": 618, "to": 763, "text": "लेकिन सोचिए, अगर आपके पास एक ऐसा AI assistant हो जो आपके चैनल को समझता हो,"}, {"from": 764, "to": 814, "text": "आपकी audience को जानता हो,"}, {"from": 815, "to": 956, "text": "और आपकी content creation journey के अलग-अलग हिस्सों में आपकी मदद कर सके?"}, {"from": 969, "to": 1055, "text": "यहीं पर Claude AI आपके लिए काफी useful हो सकता है।"}, {"from": 1069, "to": 1176, "text": "आज हम सीखेंगे कि Claude को एक personal YouTube content assistant की तरह कैसे"}, {"from": 1177, "to": 1196, "text": "setup करना है।"}, {"from": 1209, "to": 1337, "text": "हम Projects, custom instructions, reference files, Skills, video ideas,"}, {"from": 1338, "to": 1458, "text": "thumbnail concepts और analytics workflows को step by step समझेंगे।"}, {"from": 1471, "to": 1548, "text": "और सबसे अच्छी बात, हम केवल theory नहीं देखेंगे।"}, {"from": 1549, "to": 1635, "text": "हर important feature का practical example भी समझेंगे।"}, {"from": 1669, "to": 1768, "text": "सबसे पहले समझते हैं कि Claude AI क्या है।"}, {"from": 1782, "to": 1907, "text": "Claude एक AI assistant है, जिसे Anthropic ने develop किया है।"}, {"from": 1920, "to": 2019, "text": "इसकी मदद से आप लिख सकते हो, जानकारी को समझ सकते हो,"}, {"from": 2020, "to": 2162, "text": "documents analyze कर सकते हो और अपने creative कामों में सहायता ले सकते हो।"}, {"from": 2176, "to": 2303, "text": "एक YouTube Creator के लिए Claude का सबसे बड़ा फायदा सिर्फ script लिखना नहीं"}, {"from": 2304, "to": 2308, "text": "है।"}, {"from": 2321, "to": 2484, "text": "असली फायदा तब मिलता है जब आप इसे अपने चैनल से जुड़ा सही context देते हो।"}, {"from": 2497, "to": 2574, "text": "मान लीजिए आप technology videos बनाते हो।"}, {"from": 2575, "to": 2705, "text": "आपका बोलने का style Hindi-Hinglish है, आपकी audience beginners हैं,"}, {"from": 2706, "to": 2802, "text": "और आप आसान examples के साथ topics explain करते हो।"}, {"from": 2816, "to": 2899, "text": "अगर Claude को ये सारी बातें मालूम हों,"}, {"from": 2900, "to": 3024, "text": "तो वह आपके लिए ज्यादा relevant content तैयार कर सकता है।"}, {"from": 3037, "to": 3145, "text": "इसीलिए हमें सबसे पहले AI को अपने चैनल के बारे में सिखाना होगा।"}, {"from": 3179, "to": 3253, "text": "अब मान लीजिए आपको एक नई वीडियो की script लिखवानी है।"}, {"from": 3266, "to": 3397, "text": "Normally आपको AI को बताना पड़ता है कि आपके चैनल का niche क्या है,"}, {"from": 3398, "to": 3518, "text": "audience कैसी है, language क्या है, वीडियो कितनी लंबी चाहिए,"}, {"from": 3519, "to": 3595, "text": "और आपका writing style कैसा होना चाहिए।"}, {"from": 3609, "to": 3665, "text": "अगर आप बार-बार अलग-अलग काम करते हो,"}, {"from": 3666, "to": 3767, "text": "तो यह सारी instructions repeat करना time-consuming हो सकता है।"}, {"from": 3781, "to": 3894, "text": "इसी problem को आसान बनाने के लिए Claude में Projects का इस्तेमाल किया जा सकता"}, {"from": 3895, "to": 3962, "text": "है, जहाँ यह feature आपके account पर उपलब्ध हो।"}, {"from": 3976, "to": 4102, "text": "Project एक dedicated workspace होता है जिसमें आप किसी खास काम के लिए relevant"}, {"from": 4103, "to": 4195, "text": "instructions और reference materials organize कर सकते हो।"}, {"from": 4209, "to": 4311, "text": "एक YouTube Creator अपने चैनल के लिए अलग Project बना सकता है।"}, {"from": 4325, "to": 4456, "text": "उसके बाद उसी workspace में नई chats शुरू करके channel-related tasks कर सकता"}, {"from": 4457, "to": 4461, "text": "है।"}, {"from": 4474, "to": 4631, "text": "इस तरह आप बार-बार शुरुआत से पूरी जानकारी लिखने की जरूरत कम कर सकते हो।"}, {"from": 4645, "to": 4755, "text": "लेकिन याद रखिए, AI का output हमेशा review करना जरूरी है,"}, {"from": 4756, "to": 4872, "text": "क्योंकि saved context होने के बाद भी AI गलतियाँ कर सकता है।"}, {"from": 4906, "to": 4950, "text": "अब practical setup समझते हैं।"}, {"from": 4963, "to": 5091, "text": "सबसे पहले Claude के Projects section में जाइए और नया Project create कीजिए।"}, {"from": 5105, "to": 5221, "text": "हम इस example में Project का नाम रखेंगे YouTube Content Assistant।"}, {"from": 5234, "to": 5330, "text": "इसके बाद आपको अपने Project का purpose clearly define करना है।"}, {"from": 5344, "to": 5388, "text": "जैसे, Help me research,"}, {"from": 5389, "to": 5509, "text": "plan and create high-quality YouTube content for my audience."}, {"from": 5523, "to": 5601, "text": "अब सबसे important हिस्सा है Project Instructions."}, {"from": 5615, "to": 5728, "text": "यहाँ आप Claude को बताएँगे कि वह आपके लिए किस role में काम करेगा।"}, {"from": 5742, "to": 5865, "text": "उदाहरण के लिए, तुम मेरे YouTube content strategy assistant हो।"}, {"from": 5866, "to": 5982, "text": "तुम्हारा काम है मुझे engaging scripts, better video ideas,"}, {"from": 5983, "to": 6100, "text": "compelling titles और thumbnail concepts बनाने में मदद करना।"}, {"from": 6114, "to": 6198, "text": "इसके साथ आपको अपने चैनल का niche, audience,"}, {"from": 6199, "to": 6294, "text": "language और writing style भी specify करना चाहिए।"}, {"from": 6308, "to": 6378, "text": "आप जितना clear और useful context दोगे,"}, {"from": 6379, "to": 6465, "text": "Claude के लिए आपके goals समझना उतना आसान होगा।"}, {"from": 6499, "to": 6591, "text": "Project Instructions में केवल चैनल का नाम लिखना काफी नहीं है।"}, {"from": 6604, "to": 6698, "text": "आपको अपनी content identity भी explain करनी चाहिए।"}, {"from": 6712, "to": 6787, "text": "सबसे पहले बताइए कि आपका ideal viewer कौन है।"}, {"from": 6801, "to": 6951, "text": "उसे किस तरह की problems face करनी पड़ती हैं? वह आपके वीडियो क्यों देखता है?"}, {"from": 6952, "to": 7040, "text": "और वीडियो देखने के बाद उसे क्या सीखना चाहिए?"}, {"from": 7053, "to": 7114, "text": "इसके बाद अपनी brand voice define कीजिए।"}, {"from": 7128, "to": 7258, "text": "आप educational content बनाते हो, entertaining videos बनाते हो,"}, {"from": 7259, "to": 7346, "text": "या documentary-style storytelling करते हो?"}, {"from": 7360, "to": 7451, "text": "आपकी भाषा formal होनी चाहिए या conversational?"}, {"from": 7452, "to": 7561, "text": "आप छोटे sentences पसंद करते हो या detailed explanation?"}, {"from": 7574, "to": 7674, "text": "इसके बाद अपने content creation workflow के बारे में बताइए।"}, {"from": 7688, "to": 7834, "text": "आपको research में मदद चाहिए, scriptwriting में, title generation में,"}, {"from": 7835, "to": 7889, "text": "या analytics analysis में?"}, {"from": 7903, "to": 8019, "text": "यह सारी information Claude को आपके लिए ज्यादा useful creative partner बनने में"}, {"from": 8020, "to": 8042, "text": "मदद कर सकती है।"}, {"from": 8076, "to": 8169, "text": "अब आता है एक बहुत useful step, reference files add करना।"}, {"from": 8183, "to": 8275, "text": "मान लीजिए आपने पिछले कुछ महीनों में कई YouTube videos upload की हैं।"}, {"from": 8289, "to": 8427, "text": "आप अपने अच्छे perform करने वाले videos की scripts को reference के तौर पर"}, {"from": 8428, "to": 8569, "text": "Project में add कर सकते हो, अगर आपके account में file upload available है।"}, {"from": 8583, "to": 8654, "text": "इससे Claude आपके writing patterns,"}, {"from": 8655, "to": 8795, "text": "explanations और content structure को better understand कर सकता है।"}, {"from": 8809, "to": 8916, "text": "इसके अलावा आप YouTube Studio से analytics data भी export कर सकते हो।"}, {"from": 8929, "to": 9010, "text": "YouTube Studio खोलिए, Analytics में जाइए,"}, {"from": 9011, "to": 9141, "text": "और जरूरत के अनुसार Advanced Mode में अपनी date range select कीजिए।"}, {"from": 9154, "to": 9269, "text": "फिर उपलब्ध export option का इस्तेमाल करके CSV data download कीजिए।"}, {"from": 9282, "to": 9383, "text": "इस data में video titles, views, impressions,"}, {"from": 9384, "to": 9493, "text": "click-through rate और दूसरे metrics हो सकते हैं।"}, {"from": 9506, "to": 9578, "text": "लेकिन केवल वही data share कीजिए जो जरूरी हो।"}, {"from": 9579, "to": 9694, "text": "Sensitive information और private details को पहले remove करना बेहतर है।"}, {"from": 9707, "to": 9767, "text": "अब आपके पास channel instructions,"}, {"from": 9768, "to": 9857, "text": "sample scripts और analytics data तीनों तैयार हैं।"}, {"from": 9891, "to": 9971, "text": "अब देखते हैं कि यह setup practical काम कैसे कर सकता है।"}, {"from": 9985, "to": 10077, "text": "अपने YouTube Project के अंदर नई chat शुरू कीजिए।"}, {"from": 10090, "to": 10125, "text": "और Claude से पूछिए,"}, {"from": 10126, "to": 10267, "text": "मेरे चैनल की audience और पिछले वीडियो topics के आधार पर पाँच नए video ideas"}, {"from": 10268, "to": 10290, "text": "suggest करो।"}, {"from": 10304, "to": 10416, "text": "Claude उपलब्ध project context और reference material को इस्तेमाल करके ideas"}, {"from": 10417, "to": 10443, "text": "तैयार कर सकता है।"}, {"from": 10456, "to": 10494, "text": "लेकिन यहाँ एक जरूरी बात है।"}, {"from": 10507, "to": 10667, "text": "AI से मिले ideas automatically trending या guaranteed successful नहीं होते।"}, {"from": 10680, "to": 10729, "text": "आपको उन्हें audience demand,"}, {"from": 10730, "to": 10852, "text": "search interest और अपने channel goals के आधार पर evaluate करना चाहिए।"}, {"from": 10865, "to": 10937, "text": "अब किसी एक topic को select करके बोलिए,"}, {"from": 10938, "to": 11074, "text": "इस idea के लिए एक engaging introduction और detailed script outline बनाओ।"}, {"from": 11087, "to": 11156, "text": "आप चाहो तो उसे examples add करने,"}, {"from": 11157, "to": 11305, "text": "भाषा आसान करने और वीडियो को ज्यादा engaging बनाने के लिए भी कह सकते हो।"}, {"from": 11318, "to": 11417, "text": "इस तरह Claude आपके research और planning process में एक useful assistant बन"}, {"from": 11418, "to": 11428, "text": "सकता है।"}, {"from": 11462, "to": 11582, "text": "अब बात करते हैं Claude के एक और interesting concept की, Skills."}, {"from": 11595, "to": 11704, "text": "Skills ऐसे reusable instructions और resources हो सकते हैं जो किसी particular"}, {"from": 11705, "to": 11777, "text": "task को repeatable तरीके से करने में मदद करते हैं।"}, {"from": 11790, "to": 11881, "text": "मान लीजिए आपको हर हफ्ते YouTube titles generate करने होते हैं।"}, {"from": 11895, "to": 12012, "text": "हर बार एक लंबा prompt लिखने के बजाय आप एक structured workflow तैयार कर सकते"}, {"from": 12013, "to": 12017, "text": "हो।"}, {"from": 12030, "to": 12141, "text": "यह workflow समझा सकता है कि अच्छे title में clarity, curiosity,"}, {"from": 12142, "to": 12233, "text": "accuracy और audience relevance कैसे balance करनी है।"}, {"from": 12246, "to": 12316, "text": "इसी तरह आप script review, intro writing,"}, {"from": 12317, "to": 12448, "text": "thumbnail brainstorming और channel analysis के लिए भी reusable instructions"}, {"from": 12449, "to": 12469, "text": "बना सकते हो।"}, {"from": 12482, "to": 12581, "text": "Skills का इस्तेमाल और उनकी availability आपके Claude product,"}, {"from": 12582, "to": 12650, "text": "plan और environment पर depend कर सकती है।"}, {"from": 12663, "to": 12781, "text": "हम इस tutorial में इनके practical concepts को समझेंगे और दिखाएँगे कि एक"}, {"from": 12782, "to": 12877, "text": "creator इन्हें अपने workflow में कैसे organize कर सकता है।"}, {"from": 12911, "to": 13061, "text": "मान लीजिए आपको जानना है कि आपके चैनल पर कौन से videos अच्छा perform कर रहे हैं"}, {"from": 13062, "to": 13142, "text": "और किन videos को improve करने की जरूरत है।"}, {"from": 13156, "to": 13256, "text": "इसके लिए आप YouTube Analytics CSV को analyze करवा सकते हो।"}, {"from": 13270, "to": 13399, "text": "एक structured reporting workflow Claude को बता सकता है कि views, impressions,"}, {"from": 13400, "to": 13509, "text": "CTR, watch time और subscriber performance कैसे summarize करनी है।"}, {"from": 13522, "to": 13545, "text": "उदाहरण के लिए,"}, {"from": 13546, "to": 13669, "text": "अगर किसी वीडियो को impressions मिल रहे हैं लेकिन click-through rate कम है,"}, {"from": 13670, "to": 13769, "text": "तो उसके title और thumbnail को review करना उपयोगी हो सकता है।"}, {"from": 13783, "to": 13897, "text": "लेकिन सिर्फ CTR देखकर पूरी performance का फैसला नहीं करना चाहिए। Topic,"}, {"from": 13898, "to": 13988, "text": "traffic source, audience और video age भी महत्वपूर्ण हैं।"}, {"from": 14001, "to": 14089, "text": "इसी तरह आप देख सकते हो कि किन videos से subscribers आए,"}, {"from": 14090, "to": 14166, "text": "किन topics पर viewers ने ज्यादा interest दिखाया,"}, {"from": 14167, "to": 14232, "text": "और कहाँ improvement के opportunities हैं।"}, {"from": 14246, "to": 14350, "text": "इस पूरी information से एक readable report card तैयार किया जा सकता है।"}, {"from": 14364, "to": 14440, "text": "अच्छी analytics केवल numbers नहीं बताती,"}, {"from": 14441, "to": 14525, "text": "बल्कि better decisions लेने में मदद करती है।"}, {"from": 14559, "to": 14657, "text": "अब एक practical example देखते हैं, Title Writer."}, {"from": 14671, "to": 14822, "text": "एक अच्छा YouTube title viewer को यह समझाने में मदद करता है कि वीडियो उसके लिए"}, {"from": 14823, "to": 14857, "text": "क्यों relevant है।"}, {"from": 14871, "to": 14971, "text": "हम Claude को instruction दे सकते हैं कि किसी भी topic के लिए पाँच या छह"}, {"from": 14972, "to": 15024, "text": "different title options generate करो।"}, {"from": 15037, "to": 15090, "text": "हर title clear हो, interesting हो,"}, {"from": 15091, "to": 15177, "text": "और वीडियो के actual content को accurately represent करे।"}, {"from": 15191, "to": 15280, "text": "साथ ही Claude से पूछ सकते हैं कि किस title में curiosity है,"}, {"from": 15281, "to": 15398, "text": "किसमें specific benefit है, और किसमें search-friendly wording इस्तेमाल हुई है।"}, {"from": 15412, "to": 15519, "text": "फिर हम इन titles को compare करके सबसे suitable option select कर सकते हैं।"}, {"from": 15533, "to": 15642, "text": "आप Claude से यह भी कह सकते हो कि title को थोड़ा छोटा करो,"}, {"from": 15643, "to": 15770, "text": "language ज्यादा natural बनाओ, या unnecessary clickbait remove करो।"}, {"from": 15784, "to": 15897, "text": "Repeated testing और feedback से आपका workflow ज्यादा consistent हो सकता है।"}, {"from": 15910, "to": 15934, "text": "लेकिन याद रखिए,"}, {"from": 15935, "to": 16058, "text": "AI-generated scores या predictions actual YouTube performance की guarantee"}, {"from": 16059, "to": 16073, "text": "नहीं हैं।"}, {"from": 16107, "to": 16241, "text": "अब बात करते हैं दो बहुत important content creation elements की,"}, {"from": 16242, "to": 16297, "text": "intro hooks और thumbnails."}, {"from": 16311, "to": 16420, "text": "YouTube पर शुरुआत के कुछ seconds viewer को यह समझाने के लिए महत्वपूर्ण होते"}, {"from": 16421, "to": 16473, "text": "हैं कि वीडियो आगे क्यों देखनी चाहिए।"}, {"from": 16487, "to": 16605, "text": "Claude की मदद से आप एक ही topic के लिए different opening hooks brainstorm कर"}, {"from": 16606, "to": 16618, "text": "सकते हो।"}, {"from": 16632, "to": 16725, "text": "जैसे एक question-based hook, एक surprising observation,"}, {"from": 16726, "to": 16839, "text": "एक problem-solution opening, या एक direct educational introduction."}, {"from": 16853, "to": 16962, "text": "फिर आप अपने चैनल की style और audience के हिसाब से सबसे natural hook choose कर"}, {"from": 16963, "to": 16973, "text": "सकते हो।"}, {"from": 16987, "to": 17042, "text": "इसके बाद आता है Thumbnail Ideation."}, {"from": 17056, "to": 17177, "text": "यहाँ आप Claude को अपना topic दे सकते हो और उससे multiple thumbnail concepts"}, {"from": 17178, "to": 17213, "text": "generate करवा सकते हो।"}, {"from": 17226, "to": 17323, "text": "हर concept के साथ आप visual composition, background colors,"}, {"from": 17324, "to": 17428, "text": "main subject और short thumbnail text के suggestions ले सकते हो।"}, {"from": 17442, "to": 17519, "text": "लेकिन final thumbnail बनाते समय readability,"}, {"from": 17520, "to": 17609, "text": "accuracy और visual clarity का ध्यान रखना जरूरी है।"}, {"from": 17622, "to": 17668, "text": "AI से ideas लेना useful है,"}, {"from": 17669, "to": 17762, "text": "लेकिन final creative judgment creator का ही होना चाहिए।"}, {"from": 17796, "to": 17864, "text": "अब इन सारे features को एक साथ जोड़कर देखते हैं।"}, {"from": 17878, "to": 17972, "text": "सबसे पहले आप अपने channel के लिए dedicated Project setup करते हो।"}, {"from": 17986, "to": 18064, "text": "फिर उसमें audience information, brand voice,"}, {"from": 18065, "to": 18173, "text": "writing preferences और relevant reference files add करते हो।"}, {"from": 18186, "to": 18277, "text": "इसके बाद Claude से नए video topics brainstorm करवा सकते हो।"}, {"from": 18291, "to": 18366, "text": "Selected topic के लिए research outline,"}, {"from": 18367, "to": 18482, "text": "engaging introduction और script structure तैयार कर सकते हो।"}, {"from": 18495, "to": 18592, "text": "Title Writer workflow से multiple titles compare कर सकते हो।"}, {"from": 18606, "to": 18688, "text": "Thumbnail Ideation से visual concepts explore कर सकते हो।"}, {"from": 18702, "to": 18846, "text": "और वीडियो publish होने के बाद analytics data की मदद से समझ सकते हो कि क्या"}, {"from": 18847, "to": 18943, "text": "अच्छा perform हुआ और क्या improve किया जा सकता है।"}, {"from": 18957, "to": 19066, "text": "इस तरह आपका workflow एक organized system बन जाता है।"}, {"from": 19080, "to": 19205, "text": "Claude आपकी creativity को replace नहीं करता। वह planning, drafting,"}, {"from": 19206, "to": 19339, "text": "analysis और repetitive tasks को manage करने में आपकी सहायता कर सकता है।"}, {"from": 19373, "to": 19493, "text": "तो अब आप समझ गए होंगे कि Claude AI को सिर्फ एक normal chatbot की तरह इस्तेमाल"}, {"from": 19494, "to": 19599, "text": "करने के बजाय एक structured content assistant कैसे बनाया जा सकता है।"}, {"from": 19612, "to": 19696, "text": "Projects से आप relevant context organize कर सकते हो।"}, {"from": 19710, "to": 19875, "text": "Skills और reusable instructions से अपने repeated tasks को streamline कर सकते"}, {"from": 19876, "to": 19881, "text": "हो।"}, {"from": 19895, "to": 20023, "text": "और analytics के साथ AI की मदद लेकर अपने content decisions को ज्यादा informed"}, {"from": 20024, "to": 20043, "text": "बना सकते हो।"}, {"from": 20057, "to": 20197, "text": "सबसे important बात, हमेशा अपने content को review करो, facts verify करो,"}, {"from": 20198, "to": 20270, "text": "और अपनी original creativity बनाए रखो।"}, {"from": 20284, "to": 20348, "text": "अगर आपको यह tutorial useful लगा,"}, {"from": 20349, "to": 20499, "text": "तो वीडियो को like कीजिए और ऐसे ही AI tools और YouTube creation tutorials के"}, {"from": 20500, "to": 20556, "text": "लिए चैनल को subscribe कीजिए।"}, {"from": 20570, "to": 20599, "text": "मिलते हैं अगली वीडियो में!"}];
